<?php $layout='layouts.app'; ?>
<div style="display:flex;justify-content:space-between"><div><h1>Notification inbox</h1><p class="muted"><?= (int)$unread ?> unread notification(s).</p></div><a class="btn btn-outline" href="/communication">Communication</a></div>
<div class="card" style="margin-top:var(--space-4)"><div class="card-body"><table class="table"><thead><tr><th>Title</th><th>Type</th><th>Published</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($messages as $message): ?><tr><td><strong><?= e($message['title']) ?></strong><div class="muted"><?= e(mb_strimwidth(strip_tags($message['body']),0,120,'…')) ?></div></td><td><?= e(ucfirst($message['type'])) ?></td><td><?= e((string)$message['published_at']) ?></td><td><?= $message['read_at']===null?'Unread':'Read' ?></td><td><?php if($message['read_at']===null): ?><form method="POST" action="/communication/<?= (int)$message['id'] ?>/read"><?= csrf() ?><button class="btn btn-outline" type="submit">Mark read</button></form><?php endif; ?></td></tr><?php endforeach; if(!$messages): ?><tr><td colspan="5">Your inbox is empty.</td></tr><?php endif; ?></tbody></table></div></div>
